args.command:
cd /workspace && python -c "
from packaging.version import Version, Specifier, InvalidVersion, InvalidSpecifier

print(repr(str(Version('1!1.0'))))
print(repr(str(Version('0100!0.0'))))
print(repr(str(Version('00!1.2'))))
for bad in ['1:1.0', '1!1.0:', '1:1.0+abc']:
    try:
        Version(bad); print('ACCEPTED(!)', bad)
    except InvalidVersion as e:
        print('rejected:', e)
for s in ['~=2!1.0', '==2!1.*', '==1!1.0', '>=1!1.0', '!=2!1.0', '==0100!0.0']:
    print('ok', s, Specifier(s))
for s in ['~=2:1.0', '==2:1.*', '==1:1.0']:
    try:
        Specifier(s); print('ACCEPTED(!)', s)
    except InvalidSpecifier as e:
        print('rejected:', e)
print(sorted(map(Version, ['1.0', '1!1.0', '1!0.9', '2.0'])))
print('1!1.0' in Specifier('==1!1.0'), '2!1.0' in Specifier('==2!1.*'), '2!1.0' in Specifier('~=2!1.0'))
print(Version('1!1.0').public, Version('1!1.0+abc').local)
"
